1	using Microsoft.EntityFrameworkCore;
2	using seed_a_backend.Api.Infrastructure;
3	
4	namespace seed_a_backend.Tests;
5	
6	public class SeedDataImporterTests : IAsyncLifetime
7	{
8	    private readonly SqlServerTestDatabase _database = new();
9	
10	    public ValueTask InitializeAsync() => _database.InitializeAsync();
11	
12	    public ValueTask DisposeAsync() => _database.DisposeAsync();
13	
14	    private static string SeedFilePath()
15	    {
16	        var directory = new DirectoryInfo(AppContext.BaseDirectory);
17	        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, "seed-a-backend.slnx")))
18	        {
19	            directory = directory.Parent;
20	        }
21	
22	        if (directory is null)
23	        {
24	            throw new InvalidOperationException("Repository-Wurzel (seed-a-backend.slnx) wurde nicht gefunden.");
25	        }
26	
27	        return Path.Combine(directory.FullName, "seed-a-backend.Api", "Data", "anfangsdatenbestand.json");
28	    }
29	
30	    [Fact]
31	    public async Task ImportIfEmptyAsync_gegen_leere_DB_befuellt_alle_Tabellen_korrekt()
32	    {
33	        var ct = TestContext.Current.CancellationToken;
34	        await using var db = _database.CreateContext();
35	        var importer = new SeedDataImporter(db);
36	
37	        await importer.ImportIfEmptyAsync(SeedFilePath(), ct);
38	
39	        Assert.Equal(2, await db.Venues.CountAsync(ct));
40	        Assert.Equal(4, await db.Rooms.CountAsync(ct));
41	        Assert.Equal(6, await db.Events.CountAsync(ct));
42	        Assert.Equal(12, await db.PriceCategories.CountAsync(ct));
43	
44	        var kleinerSaal = await db.Rooms.SingleAsync(r => r.Name == "Kleiner Saal", ct);
45	        Assert.Equal(new[] { "A", "B", "C", "D", "E", "F" }, kleinerSaal.RowLabels);
46	        Assert.Equal(10, kleinerSaal.ColumnCount);
47	        Assert.Equal(new[] { 6 }, kleinerSaal.AisleColumns);
48	
49	        var studio = await db.Rooms.SingleAsync(r => r.Name == "Studio", ct);
50	        Assert.Empty(studio.AisleColumns);
51	
52	        var kammerkonzert = await db.Events.SingleAsync(e => e.Titel == "Kammerkonzert Frühling", ct);
53	        var belegtePositionen = await db.BookingPositions
54	            .Where(bp => bp.EventId == kammerkonzert.Id)
55	            .OrderBy(bp => bp.RowLabel).ThenBy(bp => bp.ColumnNumber)
56	            .ToListAsync(ct);
57	
58	        Assert.Equal(3, belegtePositionen.Count);
59	        Assert.Collection(belegtePositionen,
60	            p => Assert.Equal(("B", 3), (p.RowLabel, p.ColumnNumber)),
61	            p => Assert.Equal(("B", 4), (p.RowLabel, p.ColumnNumber)),
62	            p => Assert.Equal(("C", 7), (p.RowLabel, p.ColumnNumber)));
63	
64	        Assert.All(belegtePositionen, p =>
65	        {
66	            Assert.Null(p.BookingId);
67	            Assert.Null(p.PriceCategoryId);
68	            Assert.Null(p.CancelledAtUtc);
69	        });
70	
71	        var sinfonisches = await db.Events.SingleAsync(e => e.Titel == "Sinfonisches Openair-Programm", ct);
72	        var keinePositionen = await db.BookingPositions.Where(bp => bp.EventId == sinfonisches.Id).CountAsync(ct);
73	        Assert.Equal(0, keinePositionen);
74	    }
75	
76	    [Fact]
77	    public async Task ImportIfEmptyAsync_zweiter_Lauf_gegen_befuellte_DB_erzeugt_keine_Duplikate()
78	    {
79	        var ct = TestContext.Current.CancellationToken;
80	        await using var db = _database.CreateContext();
81	        var importer = new SeedDataImporter(db);
82	        var seedFilePath = SeedFilePath();
83	
84	        await importer.ImportIfEmptyAsync(seedFilePath, ct);
85	        var venuesNachErstemLauf = await db.Venues.CountAsync(ct);
86	        var eventsNachErstemLauf = await db.Events.CountAsync(ct);
87	        var positionenNachErstemLauf = await db.BookingPositions.CountAsync(ct);
88	
89	        await importer.ImportIfEmptyAsync(seedFilePath, ct);
90	
91	        Assert.Equal(venuesNachErstemLauf, await db.Venues.CountAsync(ct));
92	        Assert.Equal(eventsNachErstemLauf, await db.Events.CountAsync(ct));
93	        Assert.Equal(positionenNachErstemLauf, await db.BookingPositions.CountAsync(ct));
94	    }
95	
96	    [Fact]
97	    public async Task Gefilterte_Unique_Constraint_verhindert_doppelte_aktive_Belegung_desselben_Sitzplatzes()
98	    {
99	        var ct = TestContext.Current.CancellationToken;
100	        await using var db = _database.CreateContext();
101	        var importer = new SeedDataImporter(db);
