using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using seed_a_backend.Api.Domain;
using seed_a_backend.Api.Infrastructure.SeedModels;

namespace seed_a_backend.Api.Infrastructure;

public class SeedDataImporter(AppDbContext db)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };

    public async Task ImportIfEmptyAsync(string jsonFilePath, CancellationToken ct = default)
    {
        if (await db.Venues.AnyAsync(ct))
        {
            return;
        }

        var json = await File.ReadAllTextAsync(jsonFilePath, ct);
        var data = JsonSerializer.Deserialize<SeedDataDto>(json, JsonOptions)
            ?? throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{jsonFilePath}' gelesen werden.");

        await ImportAsync(data, ct);
    }

    public async Task ImportAsync(SeedDataDto data, CancellationToken ct = default)
    {
        var eventsById = new Dictionary<string, Event>();
        var venues = new List<Venue>();

        foreach (var venueDto in data.Spielstaetten)
        {
            var venue = new Venue { Name = venueDto.Name };
            var roomsById = new Dictionary<string, Room>();

            foreach (var roomDto in venueDto.Raeume)
            {
                var room = new Room
                {
                    Name = roomDto.Name,
                    RowLabels = roomDto.Reihen,
                    ColumnCount = roomDto.Spalten,
                    AisleColumns = roomDto.Gang?.Spalten ?? new List<int>(),
                };
                venue.Rooms.Add(room);
                roomsById[roomDto.Id] = room;
            }

            foreach (var eventDto in data.Veranstaltungen.Where(e => e.SpielstaetteId == venueDto.Id))
            {
                var room = roomsById[eventDto.RaumId];
                var @event = new Event
                {
                    Titel = eventDto.Titel,
                    Beschreibung = eventDto.Beschreibung,
                    Zeitpunkt = eventDto.Zeitpunkt,
                    DauerMinuten = eventDto.DauerMinuten,
                    Altersfreigabe = eventDto.Altersfreigabe,
                };

                foreach (var priceCategoryDto in eventDto.Preiskategorien)
                {
                    @event.PriceCategories.Add(new PriceCategory
                    {
                        Name = priceCategoryDto.Name,
                        Preis = priceCategoryDto.Preis,
                    });
                }

                foreach (var sitzplatz in eventDto.BelegteSitzplaetze)
                {
                    var (rowLabel, columnNumber) = ParseSitzplatz(sitzplatz);
                    @event.BookingPositions.Add(new BookingPosition
                    {
                        RowLabel = rowLabel,
                        ColumnNumber = columnNumber,
                        BookingId = null,
                        PriceCategoryId = null,
                        CancelledAtUtc = null,
                    });
                }

                room.Events.Add(@event);
                eventsById[eventDto.Id] = @event;
            }

            venues.Add(venue);
        }

        db.Venues.AddRange(venues);
        await db.SaveChangesAsync(ct);
    }

    /// <summary>Führende Buchstaben = RowLabel, folgende Ziffern = ColumnNumber (z. B. "B3" -> ("B", 3)).</summary>
    internal static (string RowLabel, int ColumnNumber) ParseSitzplatz(string sitzplatz)
    {
        var digitsStart = 0;
        while (digitsStart < sitzplatz.Length && !char.IsDigit(sitzplatz[digitsStart]))
        {
            digitsStart++;
        }

        if (digitsStart == 0 || digitsStart == sitzplatz.Length)
        {
            throw new FormatException($"Sitzplatz '{sitzplatz}' entspricht nicht dem Format <Reihenbuchstaben><Spaltenzahl>.");
        }

        var rowLabel = sitzplatz[..digitsStart];
        var columnNumber = int.Parse(sitzplatz[digitsStart..]);
        return (rowLabel, columnNumber);
    }
}

using seed_a_backend.Api.Infrastructure;

namespace seed_a_backend.Tests;

public class SeedDataImporterParseSitzplatzTests
{
    [Theory]
    [InlineData("B3", "B", 3)]
    [InlineData("A1", "A", 1)]
    [InlineData("AA12", "AA", 12)]
    public void ParseSitzplatz_trennt_Reihenbuchstaben_und_Spaltenzahl(string sitzplatz, string erwarteteReihe, int erwarteteSpalte)
    {
        var (rowLabel, columnNumber) = SeedDataImporter.ParseSitzplatz(sitzplatz);

        Assert.Equal(erwarteteReihe, rowLabel);
        Assert.Equal(erwarteteSpalte, columnNumber);
    }

    [Theory]
    [InlineData("3")]
    [InlineData("B")]
    [InlineData("")]
    public void ParseSitzplatz_wirft_bei_ungueltigem_Format(string sitzplatz)
    {
        Assert.Throws<FormatException>(() => SeedDataImporter.ParseSitzplatz(sitzplatz));
    }
}

